import os
import re
import yaml
import moler.config as moler_config
from moler.config import devices as devices_config
from functools import wraps
from taf.ul.moler.converter.moler_converter import MolerConverter
from taf.ul.moler.converter.moler_devices import MolerDevices


def prepare_and_load_configuration(taf_tl, create_at_startup=True, logger_params=None):
    """
    Prepare and load moler configuration from taf testline configuration.

    :param taf_tl: Taf testline configuration.
    :param create_at_startup:  If set to True moler will create all device at startup.
    :param logger_params: logger configuration params.
           Possible params:
           {
            'MODE': 'write',             # 'append'
            'PATH': '/home/ute/logs/',
            'RAW_LOG': True,             # False
            'DEBUG_LEVEL': 'DEBUG',      # TRACE|DEBUG|INFO
            'DATE_FORMAT': '%d %H:%M:%S'
            }
    :return: Dictionary with moler configuration.
    """
    return MolerConverter.prepare_and_load_configuration(taf_tl=taf_tl,
                                                         create_at_startup=create_at_startup,
                                                         logger_params=logger_params)


def load_moler_configuration(tl, create_at_startup=False, logger_params=None, save_configuration=True):
    """
    Loading moler configuration before run function which needs moler configuration.
    Sample usage:
    from common.lib.utilities import get_builtin_value
    tl = get_builtin_value(param_name="tl")

    @load_moler_configuration(tl)
    def some_method_which_use_moler_device(self):
        pass

    :param tl: Taf testline configuration.
    :param create_at_startup: If set to True moler will create all device at startup.
    :param logger_params: logger configuration params.
           Possible params:
           {
            'MODE': 'write',             # 'append'
            'PATH': '/home/ute/logs/',
            'RAW_LOG': True,             # False
            'DEBUG_LEVEL': 'DEBUG',      # TRACE|DEBUG|INFO
            'DATE_FORMAT': '%d %H:%M:%S'
            }
    :param save_configuration:      If set to True moler will save configuration in a yaml file.
    :return: return wrapped function.
    """

    def _load_moler_configuration(moler_fun):
        @wraps(moler_fun)
        def wrapper(*args, **kwargs):
            if not MolerConverter.is_configuration_already_loaded():
                prepare_and_load_configuration(tl, create_at_startup=create_at_startup, logger_params=logger_params)
                if save_configuration:
                    save_moler_configuration_to_yml_file()
            result = moler_fun(*args, **kwargs)
            return result

        return wrapper
    return _load_moler_configuration


def save_moler_configuration_to_yml_file(dir_path=None):
    _log_decorator = '#' * 10
    configs = moler_config.loaded_config
    if not dir_path:
        dir_path = configs[0]['LOGGER']['PATH']
    file_path = os.path.join(dir_path, "moler_config.yml")
    with open(file_path, 'w') as output_file:
        for index, data in enumerate(configs, 1):
            if len(configs) > 1:
                if index == 1:
                    output_file.write("{} Moler CONFIG was loaded many times {}\n".
                                      format(_log_decorator, _log_decorator))
                output_file.write("{} CONFIG NUMBER {} {}\n".format(_log_decorator, index, _log_decorator))
            yaml.dump(data, output_file)
            output_file.write("\n")


def close_all_moler_connections(clear_device_history=True):
    """
    Close all moler connections.
    :param clear_device_history: set True to clear the history of devices. Caution: you may overwrite your logs!
    """
    MolerConverter.close_all_moler_connections(clear_device_history=clear_device_history)


def add_device_to_already_loaded_configuration(config, save_configuration=True, dir_path=None):
    r"""

    :param config: configuration to device
    :param save_configuration: Flag to determine whether the moler configuration shall be saved in the yaml file
    :param dir_path: Path to the yaml file
    :return: None

    Sample config:
    config = {
        'Sample_Device': {
            'DEVICE_CLASS': 'moler.device.unixremote.UnixRemote',
            'CONNECTION_HOPS': {
                'UNIX_LOCAL': {
                    'UNIX_REMOTE': {
                        'command_params': {
                            'expected_prompt': 'ute@.*(\$|#|>)\s+',
                            'host': '7-7-UTE5GCLOUDT1SK006.p01.ska-lab.nsn-rdnet.net',
                            'login': 'ute',
                            'password': 'ute',
                            'set_timeout': None
                        },
                        'execute_command': 'ssh'
                    }
                }
            },
            'INITIAL_STATE': 'UNIX_REMOTE'
        }
    }
    """
    if isinstance(config, dict):
        if 'DEVICES' not in config:
            _config = config.copy()
            config.clear()
            config['DEVICES'] = _config

    moler_config.load_config(config=config, config_type='dict')
    if save_configuration:
        save_moler_configuration_to_yml_file(dir_path=dir_path)
    return config


def add_unix_remote_device_to_already_loaded_configuration(device_name, host, login, password, **kwargs):
    md = MolerDevices()
    md.add_remote_unix_configuration(device_name=device_name, host=host, login=login, password=password, **kwargs)
    all_devices = md.get_moler_device_config()['DEVICES']
    return add_device_to_already_loaded_configuration(config=all_devices)


def get_devices_from_regex(pattern):
    """
    Get device names from regex
    :param pattern: pattern for device name
    :return: list of device names
    """
    devices = []
    compiled_pattern = re.compile(pattern)
    for device_name in devices_config.named_devices.keys():
        if compiled_pattern.search(device_name):
            devices.append(device_name)

    devices.sort()

    return devices


class converter(object):
    """converter class."""
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        """Create MolerConverter object."""
        self.converter = MolerConverter()

    def load_configuration(self):
        """
        Load moler configuration. Default is empty. Configuration should be prepared first.

        :return: Nothing.
        """
        self.converter.load_configuration()

    def prepare_configuration(self, taf_tl, create_at_startup=True, logger_params=None):
        """
        Prepare moler configuration. Convert taf config model into configuration dict required by moler.

        :param taf_tl: Taf testline configuration.
        :param create_at_startup:  If set to True moler will create all device at startup.
        :param logger_params: logger configuration params.
        :return: Nothing.
        """
        self.converter.prepare_configuration(taf_tl=taf_tl, create_at_startup=create_at_startup,
                                             logger_params=logger_params)

    def get_configuration(self):
        """
        Return moler configuration. Default is empty.

        :return: Moler test line configuration.
        """
        return self.converter.get_configuration()

    def add_device_to_existing_configuration(self, device, exception_if_exist=True):
        """
        Add device to moler configuration. Configuration should be prepared first.

        :param device: Device configuration should have the following syntax: {'DEVICE_NAME': {CONNECTION_HOPS':{...}}}.
        :param exception_if_exist: if set, the moler checks if the device exists in the given configuration.
        :return: Nothing. Raise exception:
                WrongUsage: incorrect structure. If existing configuration has not attribute.
                WrongUsage: device already exist. If provided device is in existing configuration.
                WrongUsage: wrong type. If device is not dictionary type.
        """
        self.converter.add_device_to_existing_configuration(device=device, exception_if_exist=exception_if_exist)
